import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { z } from 'zod';

/**
 * The held-out set's boundary, expressed as code.
 *
 * The claim being defended is that the held-out corpus was never read during
 * feature development. A README sentence saying so is worth very little -- the
 * whole point of a holdout is that its integrity cannot be checked after the
 * fact by anyone but the author. So it is enforced instead:
 *
 *   1. The holdout is generated by its own command, with its own config and its
 *      own model (`scripts/generate-holdout.ts`).
 *   2. The dev seed script does not import `OOD_CONFIG` at all, so no flag can
 *      point everyday tooling at the holdout.
 *   3. `assertDevOnly` throws if a held-out id reaches a dev code path.
 *   4. A static test asserts no source file outside a small allowlist imports
 *      the holdout config or reads this manifest.
 *
 * `eval/holdout.json` deliberately contains **ids and aggregate counts only** --
 * never case content, never per-case labels. Reading it tells you which cases
 * to stay away from, and nothing you could tune against.
 */

const manifestSchema = z
  .object({
    config: z.string(),
    corpus: z.literal('ood_holdout'),
    seed: z.string(),
    size: z.number().int().positive(),
    languageModel: z.string(),
    languageSource: z.string(),
    note: z.string(),
    disputeExternalIds: z.array(z.string()),
    razorpayDisputeIds: z.array(z.string()),
    evidencePackExternalIds: z.array(z.string()),
    distribution: z.record(z.string(), z.number()),
    groundTruth: z.record(z.string(), z.number()),
    byRail: z.record(z.string(), z.number()),
    hardShare: z.number(),
  })
  .strict();

export type HoldoutManifest = z.infer<typeof manifestSchema>;

export const HOLDOUT_PATH = fileURLToPath(new URL('./holdout.json', import.meta.url));

export function holdoutExists(): boolean {
  return existsSync(HOLDOUT_PATH);
}

export function loadHoldoutManifest(): HoldoutManifest {
  if (!holdoutExists()) {
    throw new Error(`no holdout manifest at ${HOLDOUT_PATH}. Run: pnpm holdout:generate`);
  }
  return manifestSchema.parse(JSON.parse(readFileSync(HOLDOUT_PATH, 'utf8')));
}

let cachedIds: Set<string> | null = null;

/** Every id the dev pipeline must never touch, in one set. */
export function heldOutIds(): Set<string> {
  if (!cachedIds) {
    const manifest = loadHoldoutManifest();
    cachedIds = new Set<string>([
      ...manifest.disputeExternalIds,
      ...manifest.razorpayDisputeIds,
      ...manifest.evidencePackExternalIds,
    ]);
  }
  return cachedIds;
}

export function isHeldOut(id: string): boolean {
  return heldOutIds().has(id);
}

export class HoldoutAccessError extends Error {
  constructor(readonly offendingIds: string[]) {
    super(
      `dev pipeline attempted to read ${offendingIds.length} held-out id(s): ` +
        `${offendingIds.slice(0, 3).join(', ')}${offendingIds.length > 3 ? ', ...' : ''}. ` +
        'The held-out set is scored once, by the eval harness, in held-out mode.',
    );
    this.name = 'HoldoutAccessError';
  }
}

/**
 * Throws if any supplied id belongs to the held-out set.
 * Call this at every boundary where dev-mode code loads disputes.
 */
export function assertDevOnly(ids: readonly string[]): void {
  const offending = ids.filter((id) => isHeldOut(id));
  if (offending.length > 0) throw new HoldoutAccessError(offending);
}
